import { expect, expectStatus, test } from "../../fixtures";

test.describe("Upload vendor documents", () => {
  test(
    "Documents cannot be added to a vendor under review",
    { tag: "@DOC-06" },
    async ({ apiAs }) => {
      // Arrange: a member creates a vendor with a name unique to this run
      const member = await apiAs("member");
      const suffix = `${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;

      const created = await expectStatus<{ id: string; status: string }>(
        await member.post("/api/vendors", {
          data: {
            name: `Doc Lock Vendor ${suffix}`,
            category: "services",
            contact_email: `doc-lock-${suffix}@example.test`,
          },
        }),
        201,
      );
      expect(created.status).toBe("draft");

      // Arrange: submitting the vendor moves it to "in_review"
      const submitted = await expectStatus<{ id: string; status: string }>(
        await member.post(`/api/vendors/${created.id}/submit`),
        200,
      );
      expect(submitted.status).toBe("in_review");

      // Act: attempt to upload a W-9 to the locked vendor
      const response = await member.post(`/api/vendors/${created.id}/documents`, {
        multipart: {
          kind: "w9",
          file: {
            name: "w9.txt",
            mimeType: "text/plain",
            buffer: Buffer.from("W-9 placeholder contents"),
          },
        },
      });

      // Assert
      const body = await expectStatus<{ error: { code: string } }>(response, 409);
      expect(body.error.code).toBe("vendor_locked");
    },
  );
});
